shader:
// Shake - premium camera-shake transition (Mister Horse style), v2: one continuous handheld camera path, no frame
// grid - it plays equally smooth at 24, 30 or 60 fps.
//  A  : starts calm while the cover zoom comes in, then swings harder and harder into the cut, every swing in a new
//       direction (the shake axis turns ~55 deg per swing).
//  CUT: sits on the fastest swing (the camera crosses the centre at full speed), so A leaves as a streak and B
//       arrives as one; the shutter never straddles the cut.
//  B  : keeps swinging with decaying amplitude, then settles dead still and sharp (exact from SK_REST).
// Path: a sine at 0.62 * hits cycles per transition (5 hits -> 3.1 cycles, ~7 Hz at 0.45 s) + 15 % at 1.5x, along an
// axis that turns with time, under an envelope 0 -> 1 (cut) -> 0 with zero slope at both ends; roll on its own slower sine.
// Cover zoom 1.15 at the peak (intensity 1, rotation 1.5; capped at 1.18, the roll gives way first); every offset /
// roll is computed inside the margin that zoom and the actual roll leave, so no edge (mirrored or black) ever shows.
// Motion blur: 48 taps, each a real moment of the camera path (offset + roll + zoom) inside a virtual shutter, in
// linear light (gamma 2), tapered, with a per-pixel static comb offset (no flicker). The shutter is shortened wherever
// the fastest screen corner would streak further than 140 px of a 1920 px long side (<= 3 px per tap): no stepping.
// RGB split: R / B weighted toward the two ends of the shutter, only around the cut (no extra fetches).
// params: intensity (amplitude + cover zoom), hits (swings across the transition, 2-6), blur (shutter, 0.5-1.2),
//         rotation (deg of roll, 0-2.5), chroma (RGB split on the cut)

const float SK_CUT = 0.5;        // = preset anchor
const float SK_REST = 0.885;     // camera dead still from here (end of the zoom-out)
const float SK_F = 0.0769231;    // one 30 fps frame at 0.45 s in progress units (the shutter's base length)
const float SK_RATE = 0.62;      // swing cycles per transition per hit (5 hits -> 3.1 cycles, ~7 Hz at 0.45 s)
const float SK_SW = 0.06;        // width of the slow-down around the cut (progress)
const float SK_SLOW = 0.45;      // how much the phase slows on the cut (0.55 of the swing rate there)
const float SK_JOLT = 0.62;      // swing amplitude away from the cut, relative to the cut swing
const float SK_ZIN = 0.26;       // cover zoom-in done
const float SK_ZOUT = 0.54;      // cover zoom-out starts
const float SK_ZK = 0.103;       // cover zoom per unit of intensity
const float SK_ZMAX = 1.18;      // cover zoom cap
const float SK_ZMIN = 0.15;      // cover zoom per unit of intensity at least, whatever the rotation
const float SK_FILL = 0.95;      // share of the cover margin a full pose uses
const float SK_LMAX = 0.0729167; // longest corner streak: 140 px of a 1920 px long side
const int SK_TAPS = 48;
const int SK_PROBES = 9;

float skIgn(vec2 p) {
  return fract(52.9829189 * fract(dot(p, vec2(0.06711056, 0.00583715))));
}

// shake envelope: 0 -> 1 -> 0, zero slope at both ends
float skEnv(float t) {
  return t < SK_CUT ? smoothstep(0.0, SK_ZIN, t) : 1.0 - smoothstep(SK_ZOUT, SK_REST, t);
}

// swing envelope: grows into the cut, decays after it (zero slope at both ends); the cut swing gets the full margin
float skAmp(float t) {
  float tau = (t - SK_CUT) / SK_SW;
  float e = t < SK_CUT ? smoothstep(0.0, 0.47, t) : 1.0 - smoothstep(0.53, SK_REST, t);
  return e * (SK_JOLT + (1.0 - SK_JOLT) * exp(-tau * tau));
}

// the shake itself, in units of the cover margin: xy = position, z = roll share. Zero crossing on the cut. The phase
// runs slower around the cut (SK_SLOW of the swing rate), so the cut swing is one long full-speed sweep (~0.2 of the
// transition) between quicker swings; the swing axis turns with time, so every swing goes in a new direction.
vec3 skSig(float t, float hitsN) {
  float tau = t - SK_CUT;
  float w = 6.2831853 * SK_RATE * hitsN * (tau - SK_SLOW * SK_SW * tanh(tau / SK_SW));
  float al = -0.85 + 6.0 * tau;
  float a = 0.85 * sin(w) + 0.15 * sin(1.5 * w);
  return vec3(a * cos(al), a * sin(al), sin(0.8 * w + 0.6)) * skAmp(t);
}

// camera at progress t -> (offset xy in height units, roll rad, zoom)
vec4 skCam(float t, float hitsN) {
  vec3 acc = skSig(t, hitsN);
  float E = skEnv(t);
  float hx = 0.5 * ratio;
  float kr = max(hx / 0.5, 0.5 / hx);
  float zi = SK_ZK * clamp(intensity, 0.0, 1.5);
  float rr = min(sin(radians(clamp(rotation, 0.0, 2.5))) * kr, max(SK_ZMAX - 1.0 - zi, 0.0));
  float zoom = 1.0 + E * min(max(zi + rr, SK_ZMIN * clamp(intensity, 0.0, 1.5)), SK_ZMAX - 1.0);
  float th = asin(clamp(E * rr / kr, 0.0, 1.0)) * acc.z;
  float c = cos(th);
  float s = abs(sin(th));
  vec2 m = max(vec2(hx - (hx * c + 0.5 * s) / zoom, 0.5 - (hx * s + 0.5 * c) / zoom), vec2(0.0));
  return vec4(acc.xy * m * SK_FILL, th, zoom);
}

vec2 skMap(vec4 c, vec2 q0) {
  float cr = cos(c.z);
  float sr = sin(c.z);
  return vec2(cr * q0.x - sr * q0.y, sr * q0.x + cr * q0.y) / c.w + c.xy;
}

vec3 skTex(bool onB, vec2 st) {
  vec3 c = vec3(0.0);
  if (onB) { c = getB(st).rgb; } else { c = getA(st).rgb; }
  return c;
}

vec4 skShake(vec2 uv) {
  float n = clamp(hits, 2.0, 6.0);
  vec2 asp = vec2(ratio, 1.0);
  vec2 q0 = (uv - 0.5) * asp;
  float dc = (progress - SK_CUT) / 0.09;
  float bc = exp(-dc * dc);                       // closeness to the cut
  // shutter ~ one frame (1.6 frames on the cut jolt), closed at the very ends
  float W = SK_F * clamp(blur, 0.0, 1.2) * (1.0 + 0.6 * bc);
  W *= clamp(progress * 8.0, 0.0, 1.0) * clamp((1.0 - progress) * 8.0, 0.0, 1.0);
  // the shutter never straddles the cut (a hard cut between a pure A streak and a pure B streak)
  bool onB = progress >= SK_CUT;
  float t0 = onB ? max(progress - 0.5 * W, SK_CUT) : progress - 0.5 * W;
  float t1 = onB ? progress + 0.5 * W : min(progress + 0.5 * W, SK_CUT - 1e-4);
  t0 = max(t0, 0.0);
  t1 = min(t1, 1.0);
  // streak cap: the fastest probe step of the 4 screen corners bounds the streak; shrink the shutter around progress
  vec2 cq = 0.5 * asp;
  vec4 cp = skCam(t0, n);
  vec2 p0 = skMap(cp, cq);
  vec2 p1 = skMap(cp, vec2(-cq.x, cq.y));
  vec2 p2 = skMap(cp, -cq);
  vec2 p3 = skMap(cp, vec2(cq.x, -cq.y));
  float vmax = 0.0;
  for (int i = 1; i < SK_PROBES; i++) {
    vec4 c = skCam(mix(t0, t1, float(i) / float(SK_PROBES - 1)), n);
    vec2 r0 = skMap(c, cq);
    vec2 r1 = skMap(c, vec2(-cq.x, cq.y));
    vec2 r2 = skMap(c, -cq);
    vec2 r3 = skMap(c, vec2(cq.x, -cq.y));
    vmax = max(vmax, max(max(length(r0 - p0), length(r1 - p1)), max(length(r2 - p2), length(r3 - p3))));
    p0 = r0; p1 = r1; p2 = r2; p3 = r3;
  }
  float L = vmax * float(SK_PROBES - 1) * skCam(0.5 * (t0 + t1), n).w;
  float lm = SK_LMAX * max(ratio, 1.0);
  if (L > lm) {
    float sc = lm / L;
    t0 = progress - (progress - t0) * sc;
    t1 = progress + (t1 - progress) * sc;
  }
  float dk = (progress - SK_CUT) / 0.075;
  float kc = 0.92 * clamp(chroma, 0.0, 1.0) * exp(-dk * dk);  // R early / B late in the shutter, around the cut only
  float jit = skIgn(floor(uv * resolution));
  vec3 acc = vec3(0.0);
  vec3 wsum = vec3(0.0);
  for (int i = 0; i < SK_TAPS; i++) {
    float f = (float(i) + jit) / float(SK_TAPS);
    vec4 c = skCam(clamp(mix(t0, t1, f), 0.0, 1.0), n);
    vec3 s = skTex(onB, skMap(c, q0) / asp + 0.5);
    float g = 2.0 * f - 1.0;
    vec3 w = (1.0 - g * g) * vec3(1.0 + kc * g, 1.0, 1.0 - kc * g);
    acc += s * s * w;                             // linear light (gamma 2)
    wsum += w;
  }
  return vec4(sqrt(acc / wsum), 1.0);
}

vec4 transition(vec2 uv) {
  vec4 res = vec4(0.0);
  if (progress <= 0.0) {
    res = getA(uv);
  } else if (progress >= 1.0) {
    res = getB(uv);
  } else {
    res = skShake(uv);
  }
  return res;
}
